1	import * as path from 'pathe';
2	
3	export interface SensitiveFinding {
4		path: string;
5		kind:
6			| 'forbidden-key'
7			| 'secret-like-value'
8			| 'pan-like-value'
9			| 'pii-like-value'
10			| 'support-claim-like-value';
11	}
12	
13	const forbiddenKeyParts = new Set([
14		'pan',
15		'cvv',
16		'cvc',
17		'card',
18		'cardholder',
19		'cardnumber',
20		'customer',
21		'email',
22		'firstname',
23		'fullname',
24		'lastname',
25		'phone',
26		'address',
27		'payment',
28		'account',
29		'accountnumber',
30		'auth',
31		'authentication',
32		'cookie',
33		'egress',
34		'secret',
35		'token',
36		'username',
37	]);
38	const tokenCharacter = charIn('0123456789._-').from('a', 'z');
39	const secretValue = createRegExp(
40		anyOf(
41			exactly('bearer').and(oneOrMore(whitespace), oneOrMore(tokenCharacter)),
42			exactly('sk_').and(
43				anyOf('live', 'test'),
44				'_',
45				oneOrMore(charIn('0123456789').from('a', 'z')),
46			),
47			exactly('-----BEGIN ').and(oneOrMore(charIn(' ').from('A', 'Z')), 'PRIVATE KEY-----'),
48		),
49		[caseInsensitive],
50	);
51	const panLike = createRegExp(digit.and(maybe(charIn(' -'))).times.between(13, 19));
52	const sha256Hex = createRegExp(
53		charIn('0123456789').from('a', 'f').times(64).at.lineStart().at.lineEnd(),
54		[caseInsensitive],
55	);
56	
57	const safeEvidenceVocabulary = [
58		'not-tested',
59		'not tested',
60		'not-established',
61		'not established',
62		'not-applicable',
63		'not applicable',
64		'nonclaim',
65		'non-claim',
66		'no support is established',
67		'no support established',
68	];
69	const sensitiveDomains = ['payment', 'customer', 'authentication'];
70	const strengtheningVocabulary = [
71		'certified',
72		'compliant',
73		'enabled',
74		'established',
75		'passed',
76		'production-ready',
77		'supported',
78		'verified',
79	];
80	
81	function hasSafeEvidenceVocabulary(value: string): boolean {
82		const lower = value.toLowerCase();
83		return (
84			safeEvidenceVocabulary.some((marker) => lower.includes(marker)) ||
85			(lower.startsWith('no ') && lower.includes('support is established'))
86		);
87	}
88	
89	function isSafeDomainKeyValue(key: string, value: unknown): boolean {
90		const normalized = key.replaceAll('-', '').replaceAll('_', '').toLowerCase();
91		if (!sensitiveDomains.some((domain) => normalized.startsWith(domain))) return false;
92		if (typeof value === 'string') return hasSafeEvidenceVocabulary(value);
93		if (Array.isArray(value))
94			return (
95				value.length > 0 &&
96				value.every((item) => typeof item === 'string' && hasSafeEvidenceVocabulary(item))
97			);
98		return false;
99	}
100	
101	function isEmailLike(value: string): boolean {
102		const isLocalCharacter = (character: string): boolean => {
103			const code = character.charCodeAt(0);
104			return (
105				(code >= 48 && code <= 57) ||
106				(code >= 65 && code <= 90) ||
107				(code >= 97 && code <= 122) ||
108				'._%+-'.includes(character)
109			);
110		};
111		const isDomainCharacter = (character: string): boolean => {
112			const code = character.charCodeAt(0);
113			return (
114				(code >= 48 && code <= 57) ||
115				(code >= 65 && code <= 90) ||
116				(code >= 97 && code <= 122) ||
117				'.-'.includes(character)
118			);
119		};
120		for (let at = value.indexOf('@'); at !== -1; at = value.indexOf('@', at + 1)) {
121			let localStart = at;
122			while (localStart > 0 && isLocalCharacter(value[localStart - 1]!)) localStart -= 1;
123			let domainEnd = at + 1;
124			while (domainEnd < value.length && isDomainCharacter(value[domainEnd]!)) domainEnd += 1;
125			const local = value.slice(localStart, at);
126			const domain = value.slice(at + 1, domainEnd);
127			const labels = domain.split('.');
128			const topLevel = labels.at(-1) ?? '';
129			if (
130				local &&
131				!local.startsWith('.') &&
132				!local.endsWith('.') &&
133				labels.length > 1 &&
134				labels.every((label) => label && !label.startsWith('-') && !label.endsWith('-')) &&
135				topLevel.length >= 2 &&
136				[...topLevel].every((character) => {
137					const code = character.charCodeAt(0);
138					return (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
139				})
140			)
141				return true;
142		}
143		return false;
144	}
145	
146	function hasSecretMarker(value: string): boolean {
147		const lower = value.toLowerCase();
148		return [
149			'api-key:',
150			'api-key=',
151			'api_key:',
152			'api_key=',
153			'authorization:',
154			'cookie:',
155			'password=',
156			'sessionid=',
157			'x-api-key:',
158		].some((marker) => lower.includes(marker));
159	}
160	
161	function isStrengthenedSensitiveDomainClaim(value: string): boolean {
162		const lower = value.toLowerCase();
163		return (
164			sensitiveDomains.some((domain) => lower.includes(domain)) &&
165			strengtheningVocabulary.some((marker) => lower.includes(marker)) &&
166			!hasSafeEvidenceVocabulary(lower)
167		);
168	}
169	
170	function hasForbiddenKeyPart(key: string): boolean {
171		const separated: string[] = [];
172		for (const character of key.replaceAll('-', '_')) {
173			if (character !== character.toLowerCase() && separated.at(-1) !== '_') separated.push('_');
174			separated.push(character.toLowerCase());
175		}
176		return separated
177			.join('')
178			.split('_')
179			.some((part) => forbiddenKeyParts.has(part));
180	}
181	
182	function isReceiptCryptographicDigest(value: string, path: string): boolean {
183		const digestPath =
184			['sha256', 'digest'].some((suffix) => path.toLowerCase().endsWith(suffix)) ||
185			path === '$.verification.deterministicCore.first' ||
186			path === '$.verification.deterministicCore.second';
187		return digestPath && sha256Hex.test(value);
188	}
