190	type EvidenceContext =
191		| 'ordinary'
192		| 'cyclonedx-components'
193		| 'cyclonedx-component'
194		| 'cyclonedx-hashes'
195		| 'cyclonedx-hash'
196		| 'runtime-verticals'
197		| 'runtime-vertical'
198		| 'runtime-lanes'
199		| 'runtime-lane'
200		| 'runtime-runs'
201		| 'runtime-run'
202		| 'runtime-journey-projection'
203		| 't124-official-tree'
204		| 't124-official-tree-row'
205		| 't138-official-tree'
206		| 't138-official-tree-row'
207		| 'corpus-conformance-applications'
208		| 'corpus-conformance-application'
209		| 'corpus-conformance-application-source';
210	
211	const runtimeObservationSchema = 'versionless.runtime-script-observation.v1';
212	const runtimeObservationRootKeys = new Set([
213		'schemaVersion',
214		'summary',
215		'boundaries',
216		'inputs',
217		'verticals',
218		'detectorMutation',
219	]);
220	const t124ProvenanceRootKeys = new Set([
221		'schemaVersion',
222		'fixture',
223		'repository',
224		'repositoryIdentity',
225		'commit',
226		'tree',
227		'archive',
228		'fileCount',
229		'officialTreeRowCount',
230		'officialTree',
231		'fileManifestSha256',
232		'acceptedGlobalMetadata',
233		'acceptedPathMetadata',
234		'files',
