241		'excludedCommittedDist',
242	]);
243	const t124OfficialTreeRowKeys = new Set(['path', 'mode', 'type', 'sha']);
244	const t138ImmutableFixtureRootKeys = new Set([
245		'schemaVersion',
246		'id',
247		'framework',
248		'repository',
249		'repositoryUrl',
250		'commit',
251		'tree',
