262	const corpusConformanceSchema = 'versionless.corpus-conformance.v1';
263	const corpusConformanceRootKeys = new Set([
264		'schemaVersion',
265		'summary',
266		'verticals',
267		'applications',
268		'frameworkLanes',
269		'coverage',
270		'integrity',
