282	const t138Tree = '2609b3fc4a63d7bccd8f187d66c141f4a7d3cadf';
283	const t138ReliedPaths = [
284		'.yarnrc.yml',
285		'LICENSE',
286		'app/api/newsletter2/route.ts',
287		'app/blog/[...slug]/page.tsx',
288		'app/layout.tsx',
289		'next.config.js',
290		'package.json',
291		'yarn.lock',
292	];
