294	function isLowercaseHex(value: unknown, length: number, requireLetter = false): value is string {
295		if (typeof value !== 'string' || value.length !== length) return false;
296		let hasLetter = false;
297		for (const character of value) {
298			if (character >= '0' && character <= '9') continue;
299			if (character >= 'a' && character <= 'f') {
300				hasLetter = true;
301				continue;
302			}
303			return false;
304		}
305		return !requireLetter || hasLetter;
306	}
307	
308	function isPortableOfficialTreePath(value: unknown): value is string {
309		if (typeof value !== 'string' || !value || path.isAbsolute(value) || value.includes('\\'))
310			return false;
311		const segments = value.split('/');
312		return segments.every((segment) => segment && segment !== '.' && segment !== '..');
313	}
314	
315	function isT124OfficialTreeRow(value: unknown): value is Record<string, unknown> {
316		if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
317		const row = value as Record<string, unknown>;
318		const keys = Object.keys(row);
319		if (
320			keys.length !== t124OfficialTreeRowKeys.size ||
321			keys.some((key) => !t124OfficialTreeRowKeys.has(key)) ||
322			!isPortableOfficialTreePath(row.path) ||
323			!isLowercaseHex(row.sha, 40)
324		)
325			return false;
326		return (
327			(row.type === 'tree' && row.mode === '040000') ||
328			(row.type === 'blob' && (row.mode === '100644' || row.mode === '100755'))
329		);
330	}
331	
332	function isT124ProvenanceDocument(value: Record<string, unknown>): boolean {
333		const keys = Object.keys(value);
334		const identity = value.repositoryIdentity;
335		const identityKeys =
336			identity !== null && typeof identity === 'object' && !Array.isArray(identity)
337				? Object.keys(identity)
338				: [];
339		return (
340			keys.length === t124ProvenanceRootKeys.size &&
341			keys.every((key) => t124ProvenanceRootKeys.has(key)) &&
342			value.schemaVersion === 'versionless.cross-source-provenance.v1' &&
343			value.fixture === 'next-killedbygoogle' &&
344			value.repository === t124Repository &&
345			identity !== null &&
346			typeof identity === 'object' &&
347			!Array.isArray(identity) &&
348			identityKeys.length === 2 &&
349			identityKeys.every((key) => key === 'fullName' || key === 'fork') &&
350			(identity as Record<string, unknown>).fullName === t124Repository &&
351			(identity as Record<string, unknown>).fork === false &&
352			value.commit === t124Commit &&
353			value.tree === t124Tree &&
354			value.officialTreeRowCount === 86 &&
355			Array.isArray(value.officialTree) &&
356			value.officialTree.length === 86 &&
357			value.officialTree.every(isT124OfficialTreeRow)
358		);
359	}
360	
361	function isT138ProvenanceDocument(value: Record<string, unknown>): boolean {
362		const keys = Object.keys(value);
363		const identity = value.repositoryIdentity;
364		const identityKeys =
365			identity !== null && typeof identity === 'object' && !Array.isArray(identity)
366				? Object.keys(identity)
367				: [];
368		const officialTree = value.officialTree;
369		return (
370			keys.length === t124ProvenanceRootKeys.size &&
371			keys.every((key) => t124ProvenanceRootKeys.has(key)) &&
372			value.schemaVersion === 'versionless.cross-source-provenance.v1' &&
373			value.fixture === 'next-tailwind-starter-blog' &&
374			value.repository === t138Repository &&
375			identity !== null &&
376			typeof identity === 'object' &&
377			!Array.isArray(identity) &&
378			identityKeys.length === 2 &&
379			identityKeys.every((key) => key === 'fullName' || key === 'fork') &&
380			(identity as Record<string, unknown>).fullName === t138Repository &&
381			(identity as Record<string, unknown>).fork === false &&
382			value.commit === t138Commit &&
383			value.tree === t138Tree &&
384			value.officialTreeRowCount === 138 &&
385			Array.isArray(officialTree) &&
386			officialTree.length === 138 &&
387			officialTree.every(isT124OfficialTreeRow) &&
388			new Set(officialTree.map((row) => (row as Record<string, unknown>).path)).size === 138
389		);
390	}
391	
392	function isT138ImmutableFixtureDocument(value: Record<string, unknown>): boolean {
393		const keys = Object.keys(value);
394		const identity = value.repositoryIdentity;
395		const identityKeys =
396			identity !== null && typeof identity === 'object' && !Array.isArray(identity)
397				? Object.keys(identity)
398				: [];
399		return (
400			keys.length === t138ImmutableFixtureRootKeys.size &&
401			keys.every((key) => t138ImmutableFixtureRootKeys.has(key)) &&
402			value.schemaVersion === 'versionless.immutable-fixture.v1' &&
403			value.id === 'next-tailwind-starter-blog' &&
404			value.framework === 'nextjs' &&
405			value.repository === t138Repository &&
406			value.repositoryUrl === 'https://github.com/timlrx/tailwind-nextjs-starter-blog' &&
407			identity !== null &&
408			typeof identity === 'object' &&
409			!Array.isArray(identity) &&
410			identityKeys.length === 2 &&
411			identityKeys.every((key) => key === 'fullName' || key === 'fork') &&
412			(identity as Record<string, unknown>).fullName === t138Repository &&
413			(identity as Record<string, unknown>).fork === false &&
414			value.commit === t138Commit &&
415			value.tree === t138Tree &&
416			JSON.stringify(value.reliedPaths) === JSON.stringify(t138ReliedPaths) &&
417			value.archive !== null &&
418			typeof value.archive === 'object' &&
419			!Array.isArray(value.archive) &&
420			typeof value.archiveManifestSha256 === 'string' &&
421			value.corroboratedLeadFacts !== null &&
422			typeof value.corroboratedLeadFacts === 'object' &&
423			!Array.isArray(value.corroboratedLeadFacts) &&
424			Array.isArray(value.evidenceBlockers) &&
425			value.usableClosure !== null &&
426			typeof value.usableClosure === 'object' &&
427			!Array.isArray(value.usableClosure) &&
428			Array.isArray(value.localityBoundaries) &&
429			Array.isArray(value.nonclaims)
430		);
431	}
432	
433	function targetsT138ProvenanceContext(value: Record<string, unknown>): boolean {
434		const markers = [
435			value.schemaVersion === 'versionless.cross-source-provenance.v1',
436			value.fixture === 'next-tailwind-starter-blog',
437			value.repository === t138Repository,
438			value.commit === t138Commit,
439			value.tree === t138Tree,
440			value.officialTreeRowCount === 138,
441		].filter(Boolean).length;
442		return markers >= 2;
443	}
444	
445	function isCycloneDx17Document(value: Record<string, unknown>): boolean {
446		return (
447			value.bomFormat === 'CycloneDX' &&
448			value.specVersion === '1.7' &&
449			value.version === 1 &&
450			Array.isArray(value.components)
451		);
452	}
453	
454	function isRuntimeObservationDocument(value: Record<string, unknown>): boolean {
455		const keys = Object.keys(value);
456		return (
457			value.schemaVersion === runtimeObservationSchema &&
458			Array.isArray(value.verticals) &&
459			keys.length === runtimeObservationRootKeys.size &&
460			keys.every((key) => runtimeObservationRootKeys.has(key))
461		);
462	}
463	
464	function isCorpusConformanceDocument(value: Record<string, unknown>): boolean {
465		const keys = Object.keys(value);
466		return (
467			value.schemaVersion === corpusConformanceSchema &&
468			Array.isArray(value.applications) &&
469			Array.isArray(value.verticals) &&
470			keys.length === corpusConformanceRootKeys.size &&
471			keys.every((key) => corpusConformanceRootKeys.has(key))
472		);
473	}
474	
475	function childContext(
476		context: EvidenceContext,
477		key: string,
478		rootIsCycloneDx17: boolean,
479		rootIsRuntimeObservation: boolean,
480		rootIsT124Provenance: boolean,
481		rootIsT138Provenance: boolean,
482		rootIsCorpusConformance: boolean,
483	): EvidenceContext {
484		if (rootIsCycloneDx17 && key === 'components') return 'cyclonedx-components';
485		if (context === 'cyclonedx-component' && key === 'hashes') return 'cyclonedx-hashes';
486		if (rootIsRuntimeObservation && key === 'verticals') return 'runtime-verticals';
487		if (context === 'runtime-vertical' && key === 'lanes') return 'runtime-lanes';
488		if (context === 'runtime-lane' && key === 'runs') return 'runtime-runs';
489		if (context === 'runtime-run' && key === 'journeyProjection')
490			return 'runtime-journey-projection';
491		if (rootIsT124Provenance && key === 'officialTree') return 't124-official-tree';
492		if (rootIsT138Provenance && key === 'officialTree') return 't138-official-tree';
493		if (rootIsCorpusConformance && key === 'applications') return 'corpus-conformance-applications';
494		if (context === 'corpus-conformance-application' && key === 'source')
495			return 'corpus-conformance-application-source';
496		return 'ordinary';
497	}
498	
499	function arrayItemContext(context: EvidenceContext): EvidenceContext {
500		if (context === 'cyclonedx-components') return 'cyclonedx-component';
501		if (context === 'cyclonedx-hashes') return 'cyclonedx-hash';
502		if (context === 'runtime-verticals') return 'runtime-vertical';
503		if (context === 'runtime-lanes') return 'runtime-lane';
504		if (context === 'runtime-runs') return 'runtime-run';
505		if (context === 't124-official-tree') return 't124-official-tree-row';
506		if (context === 't138-official-tree') return 't138-official-tree-row';
507		if (context === 'corpus-conformance-applications') return 'corpus-conformance-application';
508		return 'ordinary';
509	}
510	
511	function isCanonicalRuntimeObservationUsername(
512		value: unknown,
513		key: string,
514		context: EvidenceContext,
515	): boolean {
516		return context === 'runtime-journey-projection' && key === 'username' && value === 'octocat';
517	}
518	
519	function isCycloneDxSha256Content(
520		value: string,
521		key: string,
522		parent: Record<string, unknown>,
523		context: EvidenceContext,
524	): boolean {
525		return (
526			context === 'cyclonedx-hash' &&
527			key === 'content' &&
528			parent.alg === 'SHA-256' &&
529			sha256Hex.test(value)
530		);
531	}
532	
533	function isT124OfficialTreeObjectId(value: string, key: string, context: EvidenceContext): boolean {
534		return context === 't124-official-tree-row' && key === 'sha' && isLowercaseHex(value, 40, true);
535	}
536	
537	function isT138OfficialTreeObjectId(value: string, key: string, context: EvidenceContext): boolean {
538		return context === 't138-official-tree-row' && key === 'sha' && isLowercaseHex(value, 40, true);
539	}
540	
541	/**
542	 * Admits a source-application git object id published by derived corpus and
543	 * trust provenance.
544	 *
545	 * A Git revision is a forty-character lowercase hex object id, and some of them
546	 * — HospitalRun's `8156955145551d0366df10faa28e724f3377dea1` among them — open
547	 * with a thirteen-digit run that is indistinguishable from a primary account
548	 * number to the digit-run detector. The admission is deliberately as narrow as
549	 * the object id itself: the value must be exactly forty lowercase hex
550	 * characters including at least one letter, it must sit under one of the
551	 * closed revision-context keys, and that key must sit on the `source` record of
552	 * a source application inside a document whose root is exactly the derived
553	 * corpus-conformance shape. A bare digit run, a wrong-length or upper-case
554	 * value, an object id under any other key, and an object id in any other
555	 * document all keep tripping the detector.
556	 */
557	function isCorpusProvenanceRevisionObjectId(
558		value: string,
559		key: string,
560		context: EvidenceContext,
561	): boolean {
562		return (
563			context === 'corpus-conformance-application-source' &&
564			corpusProvenanceRevisionKeys.has(key) &&
565			isLowercaseHex(value, 40, true)
566		);
567	}
568	
569	function collectSensitiveSignals(
570		value: unknown,
571		path: string,
572		findings: SensitiveFinding[],
573		context: EvidenceContext,
574	): void {
575		if (Array.isArray(value)) {
576			const itemContext = arrayItemContext(context);
577			value.forEach((item, index) =>
578				collectSensitiveSignals(item, `${path}[${index}]`, findings, itemContext),
579			);
580		} else if (value !== null && typeof value === 'object') {
581			const record = value as Record<string, unknown>;
582			const rootIsCycloneDx17 = path === '$' && isCycloneDx17Document(record);
583			const rootIsRuntimeObservation = path === '$' && isRuntimeObservationDocument(record);
584			const rootIsT124Provenance = path === '$' && isT124ProvenanceDocument(record);
585			const rootIsT138Provenance = path === '$' && isT138ProvenanceDocument(record);
586			const rootIsT138ImmutableFixture = path === '$' && isT138ImmutableFixtureDocument(record);
587			const rootIsCorpusConformance = path === '$' && isCorpusConformanceDocument(record);
588			if (
589				path === '$' &&
590				targetsT138ProvenanceContext(record) &&
591				!rootIsT138Provenance &&
592				!rootIsT138ImmutableFixture
593			)
594				findings.push({ path, kind: 'pan-like-value' });
595			for (const [key, child] of Object.entries(record)) {
596				const childPath = `${path}.${key}`;
597				if (
598					hasForbiddenKeyPart(key) &&
599					!isSafeDomainKeyValue(key, child) &&
600					!isCanonicalRuntimeObservationUsername(child, key, context)
601				)
602					findings.push({ path: childPath, kind: 'forbidden-key' });
603				if (typeof child === 'string') {
604					if (secretValue.test(child) || hasSecretMarker(child))
605						findings.push({ path: childPath, kind: 'secret-like-value' });
606					if (isEmailLike(child)) findings.push({ path: childPath, kind: 'pii-like-value' });
607					if (isStrengthenedSensitiveDomainClaim(child))
608						findings.push({ path: childPath, kind: 'support-claim-like-value' });
609					const digest =
610						isReceiptCryptographicDigest(child, childPath) ||
611						isCycloneDxSha256Content(child, key, record, context) ||
612						isT124OfficialTreeObjectId(child, key, context) ||
613						isT138OfficialTreeObjectId(child, key, context) ||
614						isCorpusProvenanceRevisionObjectId(child, key, context);
615					if (!digest && panLike.test(child))
616						findings.push({ path: childPath, kind: 'pan-like-value' });
617				} else {
618					collectSensitiveSignals(
619						child,
620						childPath,
621						findings,
622						childContext(
623							context,
624							key,
625							rootIsCycloneDx17,
626							rootIsRuntimeObservation,
627							rootIsT124Provenance,
628							rootIsT138Provenance,
629							rootIsCorpusConformance,
630						),
631					);
632				}
633			}
634		} else if (typeof value === 'string') {
635			if (secretValue.test(value) || hasSecretMarker(value))
636				findings.push({ path, kind: 'secret-like-value' });
637			if (isEmailLike(value)) findings.push({ path, kind: 'pii-like-value' });
638			if (isStrengthenedSensitiveDomainClaim(value))
639				findings.push({ path, kind: 'support-claim-like-value' });
640			if (!isReceiptCryptographicDigest(value, path) && panLike.test(value))
641				findings.push({ path, kind: 'pan-like-value' });
642		}
643	}
644	
645	export function findSensitiveSignals(
646		value: unknown,
647		path = '$',
648		findings: SensitiveFinding[] = [],
649	): SensitiveFinding[] {
650		collectSensitiveSignals(value, path, findings, 'ordinary');
651		return findings;
652	}
653	
654	export function assertSyntheticEvidence(value: unknown): void {
655		const findings = findSensitiveSignals(value);
656		if (findings.length) throw new Error(`Sensitive material refused: ${JSON.stringify(findings)}`);
657	}
658	import {
659		anyOf,
660		caseInsensitive,
661		charIn,
662		createRegExp,
663		digit,
664		exactly,
665		maybe,
666		oneOrMore,
667		whitespace,
668	} from 'magic-regexp';
